fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    // Given the problem statement, `arr` is guaranteed non-empty and rectangular.
    let rows = arr.len();
    let cols = arr[0].len();

    // Prepare a vector of `cols` rows, each with capacity `rows`.
    let mut result: Vec<Vec<i8>> = vec![Vec::with_capacity(rows); cols];

    // For each row in the original matrix, push each element
    // to its transposed position.
    for row in arr {
        for j in 0..cols {
            result[j].push(row[j]);
        }
    }

    result
}

